class Solution:
    def partitionString(self, s: str) -> int:
        n = len(s)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            cnt = [0] * 26
            mx = dist = 0
            for j in range(i - 1, -1, -1):
                c = ord(s[j]) - 97
                if cnt[c] == 0:
                    dist += 1
                cnt[c] += 1
                mx = max(mx, cnt[c])
                if mx * dist == i - j and dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1
        return dp[n]

