class Solution {
public:
    int partitionString(string s) {
        int n = s.size();
        vector<int> dp(n + 1, INT_MAX);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            int cnt[26] = {0}, mx = 0, dist = 0;
            for (int j = i - 1; j >= 0; j--) {
                int c = s[j] - 'a';
                if (cnt[c]++ == 0) dist++;
                mx = max(mx, cnt[c]);
                if (mx * dist == i - j && dp[j] != INT_MAX)
                    dp[i] = min(dp[i], dp[j] + 1);
            }
        }
        return dp[n];
    }
};

