from functools import lru_cache

class Solution:
    def partitionString(self, s: str) -> int:
        n = len(s)
        @lru_cache(maxsize=None)
        def best(i):
            if i == n:
                return 0
            cnt = [0] * 26
            mx = dist = 0
            res = float('inf')
            for k in range(i, n):
                c = ord(s[k]) - 97
                if cnt[c] == 0:
                    dist += 1
                cnt[c] += 1
                mx = max(mx, cnt[c])
                if mx * dist == k - i + 1:
                    res = min(res, 1 + best(k + 1))
            return res
        return best(0)

