class Solution {
    String s;
    int n;
    int[] memo;
    int best(int i) {
        if (i == n) return 0;
        if (memo[i] != -1) return memo[i];
        int[] cnt = new int[26];
        int mx = 0, dist = 0, res = Integer.MAX_VALUE;
        for (int k = i; k < n; k++) {
            int c = s.charAt(k) - 'a';
            if (cnt[c]++ == 0) dist++;
            mx = Math.max(mx, cnt[c]);
            if (mx * dist == k - i + 1)
                res = Math.min(res, 1 + best(k + 1));
        }
        return memo[i] = res;
    }
    public int partitionString(String str) {
        s = str; n = s.length();
        memo = new int[n];
        java.util.Arrays.fill(memo, -1);
        return best(0);
    }
}

